import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';
import { auditLines } from '../support/audit';

// A draft can be spread over monthly instalments (invoices[].instalments, 2 to 24, and
// invoices[].instalmentRate, an annual rate from 0 to 30 with up to two decimals, from the plan
// form). The schedule is an ordinary loan of the grand total: monthly rate i = annual rate / 12 /
// 100; the instalment is P x i / (1 - (1 + i)^-n), rounded half up to the cent (P / n at 0%); each
// month's interest is the balance still owed x i, rounded half up to the cent, its principal the
// instalment minus the interest, and the last instalment pays off the whole remaining balance plus
// its interest so the schedule ends at exactly zero. Instalment k is due k months after the issue
// date on the same day (the month's last day when shorter). Each instalment row shows its due date,
// payment, interest, principal and remaining balance; the plan total is the sum of the instalments
// and the amount due is the plan total minus what is paid. Sending dates the schedule from the new
// issue date. An invoice with retention can't have a plan, and credit is not used on a planned
// invoice.
test.describe('instalment plans', () => {
  test('spreads a draft over monthly instalments', { tag: '@core' }, async ({ page }) => {
    await resetAndSeed({
      asOf: '2026-01-31',
      clients: [{ id: 1, name: 'Acme Ltd', email: 'ops@acme.example' }],
      invoices: [
        { id: 1, clientId: 1, status: 'DRAFT', issueDate: '2026-01-31', dueDate: '2026-02-28',
          lineItems: [{ id: 1, description: 'Consulting', qty: 1, unitPrice: 1000 }] },
      ],
    });
    await page.goto('/');

    await page.getByTestId('client-row-1').click();
    await page.getByTestId('invoice-row-1').click();
    await page.getByTestId('plan-form-count').fill('3');
    await page.getByTestId('plan-form-rate').fill('12');
    await page.getByTestId('plan-form-submit').click();
    // i = 12 / 12 / 100 = 0.01; 1000 x 0.01 / (1 - 1.01^-3) = 340.0221 -> 340.02
    // month 1: 1000.00 x 0.01 = 10.00 interest, 330.02 principal, 669.98 left; month 2: 6.6998 ->
    // 6.70, 333.32, 336.66 left; the last pays the 336.66 left plus 3.3666 -> 3.37 = 340.03
    // due on the 31st of each month, or the month's last day: 02-28, 03-31, 04-30
    await expect(page.getByTestId('instalment-row-1').getByTestId('instalment-due')).toHaveText('2026-02-28');
    await expect(page.getByTestId('instalment-row-1').getByTestId('instalment-payment')).toHaveText('$340.02');
    await expect(page.getByTestId('instalment-row-1').getByTestId('instalment-interest')).toHaveText('$10.00');
    await expect(page.getByTestId('instalment-row-1').getByTestId('instalment-principal')).toHaveText('$330.02');
    await expect(page.getByTestId('instalment-row-1').getByTestId('instalment-balance')).toHaveText('$669.98');
    await expect(page.getByTestId('instalment-row-2').getByTestId('instalment-due')).toHaveText('2026-03-31');
    await expect(page.getByTestId('instalment-row-2').getByTestId('instalment-payment')).toHaveText('$340.02');
    await expect(page.getByTestId('instalment-row-2').getByTestId('instalment-interest')).toHaveText('$6.70');
    await expect(page.getByTestId('instalment-row-2').getByTestId('instalment-principal')).toHaveText('$333.32');
    await expect(page.getByTestId('instalment-row-2').getByTestId('instalment-balance')).toHaveText('$336.66');
    await expect(page.getByTestId('instalment-row-3').getByTestId('instalment-due')).toHaveText('2026-04-30');
    await expect(page.getByTestId('instalment-row-3').getByTestId('instalment-payment')).toHaveText('$340.03');
    await expect(page.getByTestId('instalment-row-3').getByTestId('instalment-interest')).toHaveText('$3.37');
    await expect(page.getByTestId('instalment-row-3').getByTestId('instalment-principal')).toHaveText('$336.66');
    await expect(page.getByTestId('instalment-row-3').getByTestId('instalment-balance')).toHaveText('$0.00');
    await expect(page.getByTestId('invoice-plan-total')).toHaveText('$1,020.07');
    await expect(page.getByTestId('invoice-amount-due')).toHaveText('$1,020.07');

    await page.getByTestId('invoice-send').click();
    await expect(page.getByTestId('invoice-panel-status')).toHaveText('Sent');
    await expect(page.getByTestId('invoice-amount-due')).toHaveText('$1,020.07');
    await expect.poll(() => auditLines()).toContain('INVOICE_SENT id=1 number=INV-0000018 total=1000.00');
  });

  test('sending dates the instalments from the day it is sent', { tag: '@core' }, async ({ page }) => {
    await resetAndSeed({
      asOf: '2026-03-31',
      clients: [{ id: 1, name: 'Acme Ltd', email: 'ops@acme.example' }],
      invoices: [
        { id: 2, clientId: 1, status: 'DRAFT', issueDate: '2026-02-15', dueDate: '2026-03-31', instalments: 3,
          instalmentRate: 0,
          lineItems: [{ id: 1, description: 'Licence', qty: 1, unitPrice: 100 }] },
      ],
      payments: [{ id: 1, clientId: 1, amount: 50, date: '2026-03-01', allocations: [] }],
    });
    await page.goto('/');

    await page.getByTestId('client-row-1').click();
    await page.getByTestId('invoice-row-2').click();
    // at 0% each instalment is 100.00 / 3 = 33.33 and the last pays the rest
    await expect(page.getByTestId('instalment-row-1').getByTestId('instalment-due')).toHaveText('2026-03-15');
    await expect(page.getByTestId('instalment-row-3').getByTestId('instalment-payment')).toHaveText('$33.34');
    await page.getByTestId('invoice-send').click();
    // issued 2026-03-31: due 04-30, 05-31, 06-30
    await expect(page.getByTestId('instalment-row-1').getByTestId('instalment-due')).toHaveText('2026-04-30');
    await expect(page.getByTestId('instalment-row-2').getByTestId('instalment-due')).toHaveText('2026-05-31');
    await expect(page.getByTestId('instalment-row-3').getByTestId('instalment-due')).toHaveText('2026-06-30');
    await expect(page.getByTestId('instalment-row-1').getByTestId('instalment-payment')).toHaveText('$33.33');
    // the client's 50.00 credit is not used on a planned invoice
    await expect(page.getByTestId('invoice-paid')).toHaveText('$0.00');
    await expect(page.getByTestId('invoice-amount-due')).toHaveText('$100.00');
    await expect(page.getByTestId('client-row-1').getByTestId('client-credit')).toHaveText('$50.00');
    expect(auditLines().filter((l) => l.startsWith('PAYMENT_RECORDED'))).toEqual([]);
  });

  test('refuses a plan that breaks a rule', { tag: '@error' }, async ({ page }) => {
    await resetAndSeed({
      asOf: '2026-03-10',
      clients: [{ id: 1, name: 'Acme Ltd', email: 'ops@acme.example' }],
      invoices: [
        { id: 3, clientId: 1, status: 'DRAFT', issueDate: '2026-03-01', dueDate: '2026-04-30',
          lineItems: [{ id: 1, description: 'Licence', qty: 1, unitPrice: 100 }] },
        { id: 4, clientId: 1, status: 'DRAFT', issueDate: '2026-03-01', dueDate: '2026-04-30',
          retentionPct: 5,
          lineItems: [{ id: 2, description: 'Build', qty: 1, unitPrice: 100 }] },
      ],
    });
    await page.goto('/');

    await page.getByTestId('client-row-1').click();
    await page.getByTestId('invoice-row-3').click();
    const bad = [
      ['1', '12'],       // at least 2 instalments
      ['25', '12'],      // at most 24
      ['2.5', '12'],     // a whole number
      ['3', '30.01'],    // a rate from 0 to 30
      ['3', '-1'],
      ['3', '12.345'],   // at most two decimals
    ];
    for (const [count, rate] of bad) {
      await page.getByTestId('plan-form-count').fill(count);
      await page.getByTestId('plan-form-rate').fill(rate);
      await page.getByTestId('plan-form-submit').click();
      await expect(page.getByTestId('plan-form-error')).toBeVisible();
    }
    await expect(page.getByTestId(/^instalment-row-\d+$/)).toHaveCount(0);
    // invoice 4 holds back retention, so it can't also have a plan
    await page.getByTestId('invoice-row-4').click();
    await expect(page.getByTestId('invoice-panel-number')).toHaveText(await page.getByTestId('invoice-row-4').getByTestId('invoice-number').innerText());
    await page.getByTestId('plan-form-count').fill('3');
    await page.getByTestId('plan-form-rate').fill('12');
    await page.getByTestId('plan-form-submit').click();
    await expect(page.getByTestId('plan-form-error')).toBeVisible();
    await expect(page.getByTestId(/^instalment-row-\d+$/)).toHaveCount(0);
  });
});
# OfficeHQ

A full-stack office-management web application.

- **Front end:** Angular single-page app (standalone components, lazy routes), built into
  `src/main/resources/static`.
- **Back end:** Spring Boot with Spring MVC `@RestController` endpoints, on an in-memory H2 database
  with Flyway migrations run on boot.

## Build and run

```
bin/build              # build the SPA and package one runnable jar
PORT=3000 bin/start    # start the app (serves the SPA + REST on $PORT)
bin/stop               # stop it
```

Readiness: `GET /actuator/health`.

## Tests

End-to-end tests use Playwright (in `e2e/`) and bind to `data-testid`:

```
bin/e2e                # build, start, run the specs in e2e/specs, then stop
```
