370	    public void setDueDate(LocalDate dueDate) {
371	        if (issueDate != null && dueDate.isBefore(issueDate)) {
372	            throw new InvoiceRejectedException(
373	                    "The due date cannot be before the issue date (" + issueDate + ").");
374	        }
375	        if (issueDate != null && dueDate.isAfter(issueDate.plusDays(MAX_DUE_DAYS))) {
376	            throw new InvoiceRejectedException("The due date can be at most " + MAX_DUE_DAYS
377	                    + " days after the issue date, so no later than " + issueDate.plusDays(MAX_DUE_DAYS) + ".");
378	        }
379	        this.dueDate = dueDate;
380	        this.manualDueDate = true;
381	    }
382	
383	    /**
384	     * Marks the invoice sent, issued on the given date and due on the given date, unless its due date
385	     * was set by hand, which is kept.
386	     */
387	    public void markSent(LocalDate issueDate, LocalDate dueDate) {
388	        this.status = InvoiceStatus.SENT;
389	        this.issueDate = issueDate;
390	        if (!manualDueDate) {
391	            this.dueDate = dueDate;
392	        }
393	    }
394	
395	    /** Whether a due date set by hand is already past on the given send date. */
396	    public boolean dueDatePassedBy(LocalDate sendDate) {
397	        return manualDueDate && dueDate != null && dueDate.isBefore(sendDate);
398	    }
399	
400	    /** Puts a sent invoice back to draft, so it has to be sent again. */
401	    public void reopen() {
402	        this.status = InvoiceStatus.DRAFT;
403	    }
404	
405	    /** Days past its due date an invoice is given before it becomes overdue: a week's grace. */
406	    public static final int GRACE_DAYS = 7;
407	
408	    /**
409	     * The status on the given day once the given amount has been paid against the grand total at the
410	     * tax rate: a sent invoice with something still due more than {@link #GRACE_DAYS} days after its
411	     * due date is overdue, part paid or not. Held retention is never due, so never makes it overdue;
412	     * released retention is due {@link #RETENTION_DUE_DAYS} days after its release, and payments go to
413	     * the rest of the invoice before it.
414	     */
415	    public InvoiceStatus statusWhenPaid(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
416	        return statusWhenPaid(paid, null, taxRate, today);
417	    }
418	
419	    /**
420	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
421	     * paid date (null when not known) is after its due date is paid late.
422	     */
423	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
424	        if (status != InvoiceStatus.SENT) {
425	            return status;
426	        }
427	        BigDecimal amountDue = amountDue(paid, taxRate);
428	        boolean due = amountDue.signum() > 0;
429	        BigDecimal retentionDue = amountDue.min(retentionReleased(taxRate)).max(BigDecimal.ZERO);
430	        boolean restDue = amountDue.subtract(retentionDue).signum() > 0;
431	        if (restDue && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
432	            return InvoiceStatus.OVERDUE;
433	        }
434	        if (retentionDue.signum() > 0 && today.isAfter(retentionDueDate().plusDays(GRACE_DAYS))) {
435	            return InvoiceStatus.OVERDUE;
436	        }
437	        if (!due && retentionHeld(taxRate).signum() > 0) {
438	            return InvoiceStatus.RETENTION_HELD;
439	        }
440	        if (paid.signum() <= 0) {
441	            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
442	        }
443	        if (due) {
444	            return InvoiceStatus.PART_PAID;
445	        }
446	        return paidOn != null && dueDate != null && paidOn.isAfter(dueDate) ? InvoiceStatus.PAID_LATE
447	                : InvoiceStatus.PAID;
448	    }
449	
450	    /**
451	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
452	     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
453	     * counts on the day it was applied); null while something is still due or retention is held.
454	     */
455	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
456	        BigDecimal total = payable(taxRate);
457	        if (status != InvoiceStatus.SENT || total.signum() <= 0 || retentionHeld(taxRate).signum() > 0) {
458	            return null;
459	        }
460	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
461	        }
462	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
463	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
464	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
465	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
466	        BigDecimal sum = BigDecimal.ZERO;
467	        for (Part p : inOrder) {
468	            sum = sum.add(p.amount());
469	            if (sum.signum() > 0 && total.subtract(sum).compareTo(WRITE_OFF_LIMIT) < 0) {
470	                return p.on();
471	            }
472	        }
473	        return null;
474	    }
475	
476	    /**
477	     * What is still due once the given amount has been paid: the grand total less it, less what credit
478	     * notes have credited, less the retention still held, less anything written off — so nothing once
479	     * payments leave less than {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
480	     */
481	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
482	        if (isCreditNote()) {
483	            return BigDecimal.ZERO.setScale(2);
484	        }
485	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
486	    }
487	
488	    /**
489	     * What is written off once the given amount has been paid: when payments leave less than
490	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
491	     */
492	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
493	        BigDecimal left = payable(taxRate).subtract(paid);
494	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && left.compareTo(WRITE_OFF_LIMIT) < 0
495	                ? left.setScale(2, RoundingMode.HALF_UP)
496	                : BigDecimal.ZERO.setScale(2);
497	    }
498	
499	    /** The least a part payment may be at the tax rate: {@link #MINIMUM_PART_SHARE} of the grand total. */
500	    public BigDecimal minimumPart(BigDecimal taxRate) {
501	        return total(taxRate).multiply(MINIMUM_PART_SHARE).setScale(2, RoundingMode.HALF_UP);
502	    }
503	
504	    /**
505	     * Whether paying the amount on top of what was already paid is too small a part payment: under
506	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
507	     */
508	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
509	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
510	    }
511	
512	    /** Adds a line to the end of the invoice. */
513	    public void addLine(InvoiceLine line) {
514	        lines.add(line);
515	    }
516	
517	    /** Whether the invoice has the line with the given id. */
518	    public boolean hasLine(Long lineId) {
519	        return lines.stream().anyMatch(l -> lineId.equals(l.getId()));
520	    }
521	
522	    /**
523	     * Removes the line with the given id; whether the invoice had it. Refused when what is left would
524	     * be less than a fixed discount on the invoice.
525	     */
526	    public boolean removeLine(Long lineId) {
527	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
528	        if (line == null) {
529	            return false;
530	        }
531	        BigDecimal left = subtotal().subtract(line.amount());
532	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
533	            throw new InvoiceRejectedException("This line cannot be removed: the $"
534	                    + left.setScale(2).toPlainString() + " left would be less than the $"
535	                    + discountAmount.setScale(2).toPlainString() + " discount.");
536	        }
537	        lines.remove(line);
538	        return true;
539	    }
540	
541	    /**
542	     * Changes the line with the given id to the given values; whether the invoice had it. Refused when
543	     * the subtotal would then be less than a fixed discount on the invoice.
544	     */
545	    public boolean updateLine(Long lineId, String description, BigDecimal qty, BigDecimal unitPrice,
546	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
547	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
548	        if (line == null) {
549	            return false;
550	        }
551	        BigDecimal changed = new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate).amount();
552	        BigDecimal left = subtotal().subtract(line.amount()).add(changed);
553	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
554	            throw new InvoiceRejectedException("This line cannot be changed: the $"
555	                    + left.setScale(2).toPlainString() + " subtotal would be less than the $"
556	                    + discountAmount.setScale(2).toPlainString() + " discount.");
557	        }
558	        line.update(description, qty, unitPrice, taxExempt, discountPct, taxRate);
559	        return true;
560	    }
561	
562	    /**
563	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
564	     * matches what a client gets by adding up the lines shown.
565	     */
566	    public BigDecimal subtotal() {
567	        return lines.stream().map(InvoiceLine::amount)
568	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
569	    }
570	
571	    /**
572	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
573	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
574	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
575	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
576	     */
577	    public BigDecimal discount() {
578	        BigDecimal discount = discountAmount.signum() > 0
579	                ? discountAmount.min(subtotal()).setScale(2, RoundingMode.HALF_UP)
580	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(2, RoundingMode.DOWN);
581	        if (discountCap == null) {
582	            return discount;
583	        }
584	        BigDecimal lineDiscounts = lines.stream().map(InvoiceLine::discount)
585	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
586	        BigDecimal left = discountCap.setScale(2, RoundingMode.HALF_UP).subtract(lineDiscounts).max(BigDecimal.ZERO.setScale(2));
587	        return discount.min(left);
588	    }
589	
590	    /**
591	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
592	     * proportion to the line amounts: each line first gets the whole cents of its exact share
593	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
594	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
595	     * equal amounts too to the lower line id. The shares add up to the discount.
596	     */
597	    public List<BigDecimal> discountShares() {
598	        BigInteger discountCents = discount().movePointRight(2).toBigIntegerExact();
599	        BigInteger subtotalCents = subtotal().movePointRight(2).toBigIntegerExact();
600	        int n = lines.size();
601	        BigInteger[] shares = new BigInteger[n];
602	        BigInteger[] leftovers = new BigInteger[n];
603	        BigInteger given = BigInteger.ZERO;
604	        for (int i = 0; i < n; i++) {
605	            if (subtotalCents.signum() == 0) {
606	                shares[i] = BigInteger.ZERO;
607	                leftovers[i] = BigInteger.ZERO;
608	            } else {
609	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
610	                // as denominator, so the remainders compare as the fractions do.
611	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount().movePointRight(2).toBigIntegerExact())
612	                        .divideAndRemainder(subtotalCents);
613	                shares[i] = qr[0];
614	                leftovers[i] = qr[1];
615	            }
616	            given = given.add(shares[i]);
617	        }
618	        List<Integer> order = new ArrayList<>();
619	        for (int i = 0; i < n; i++) {
620	            order.add(i);
621	        }
622	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
623	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount()).reversed())
624	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
625	        int left = discountCents.subtract(given).intValueExact();
626	        for (int k = 0; k < left; k++) {
627	            int i = order.get(k);
628	            shares[i] = shares[i].add(BigInteger.ONE);
629	        }
630	        List<BigDecimal> result = new ArrayList<>(n);
631	        for (BigInteger share : shares) {
632	            result.add(new BigDecimal(share, 2));
633	        }
634	        return result;
635	    }
636	
637	    /**
638	     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
639	     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
640	     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
641	     */
642	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
643	        List<BigDecimal> shares = discountShares();
644	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
645	        for (int i = 0; i < lines.size(); i++) {
646	            InvoiceLine line = lines.get(i);
647	            taxes.add(clientTaxExempt || line.isTaxExempt() ? BigDecimal.ZERO.setScale(2)
648	                    : line.amount().subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
649	                            .setScale(2, RoundingMode.HALF_UP));
650	        }
651	        return taxes;
652	    }
653	
654	    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
655	    public BigDecimal tax(BigDecimal taxRate) {
656	        return lineTaxes(taxRate).stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
657	    }
658	
659	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
660	    public BigDecimal total(BigDecimal taxRate) {
661	        return subtotal().subtract(discount()).add(tax(taxRate));
662	    }
663	}
