205	     * clears the other, and the cap (null for none) limits everything taken off, line discounts included. Empty if no such invoice. The values have already been checked; a fixed amount
206	     * over the subtotal is refused, as is a discount taking off more than a fifth of the subtotal
207	     * (after the cap) without a reason. A sent invoice with no payments goes back to draft; one with a
208	     * payment refuses it.
209	     */
210	    @Transactional
211	    public Optional<Invoice> setDiscount(Long invoiceId, BigDecimal discountPct, BigDecimal discountAmount,
212	            BigDecimal discountCap, String discountReason) {
213	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
214	        found.ifPresent(invoice -> {
215	            if (invoice.isCreditNote()) {
216	                throw new InvoiceRejectedException("A credit note has no discount.");
217	            }
218	            boolean reopened = reopenForChange(invoice, "A paid invoice cannot be given a discount.");
219	            if (discountAmount != null) {
220	                invoice.setDiscountAmount(discountAmount);
221	            } else {
222	                invoice.setDiscountPct(discountPct);
223	            }
224	            invoice.setDiscountCap(discountCap);
225	            invoice.setDiscountReason(discountReason);
226	            if (invoice.discountLacksReason()) {
227	                throw new InvoiceRejectedException(
228	                        "A discount of more than 20% of the subtotal needs a reason.");
229	            }
230	            invoices.saveAndFlush(invoice);
231	            if (reopened) {
232	                audit.record("INVOICE_REOPENED id=" + invoice.getId());
233	            }
234	        });
235	        return found;
236	    }
