257	     * Sets the percentage of a draft's grand total held back as retention; empty if no such invoice.
258	     * The percentage has already been checked; any invoice that is not a draft, or a credit note, is refused.
259	     */
260	    @Transactional
261	    public Optional<Invoice> setRetention(Long invoiceId, BigDecimal retentionPct) {
262	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
263	        found.ifPresent(invoice -> {
264	            if (invoice.isCreditNote()) {
265	                throw new InvoiceRejectedException("A credit note holds back no retention.");
266	            }
267	            if (!invoice.isDraft()) {
