276	    /**
277	     * Releases the retention held back on a sent invoice today, adding it to the amount due (falling
278	     * due {@link Invoice#RETENTION_DUE_DAYS} days later), and records it in the audit; empty if no such
279	     * invoice. Refused while anything else is still due, or when there is no retention held to release.
280	     */
281	    @Transactional
282	    public Optional<Invoice> releaseRetention(Long invoiceId) {
283	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
284	        found.ifPresent(invoice -> {
285	            if (invoice.isDraft() || invoice.isVoid() || invoice.isCreditNote()) {
286	                throw new InvoiceRejectedException("Retention can only be released on a sent invoice.");
287	            }
288	            BigDecimal rate = taxRate.percent();
289	            BigDecimal held = invoice.retentionHeld(rate);
290	            if (held.signum() <= 0) {
291	                throw new InvoiceRejectedException("There is no retention held to release.");
292	            }
293	            BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), rate);
294	            if (due.signum() > 0) {
295	                throw new InvoiceRejectedException("The retention can only be released once nothing else is due; $"
296	                        + due.setScale(2, RoundingMode.HALF_UP).toPlainString() + " is still due.");
297	            }
298	            invoice.releaseRetention(today.date());
299	            invoices.saveAndFlush(invoice);
300	            audit.record("RETENTION_RELEASED id=" + invoice.getId() + " amount=" + held.toPlainString());
301	        });
302	        return found;
303	    }
