305	    /**
306	     * Readies the invoice for a change: a draft stays as it is; a sent invoice with no payments goes
307	     * back to draft, to be sent again; an invoice with any payment is refused with the message.
308	     * Whether it went back to draft.
309	     */
310	    private boolean reopenForChange(Invoice invoice, String refusal) {
311	        if (invoice.isDraft()) {
312	            return false;
313	        }
314	        if (invoice.isVoid()) {
315	            throw new InvoiceRejectedException("A void invoice cannot be changed.");
316	        }
317	        if (invoice.isCreditNote()) {
318	            throw new InvoiceRejectedException("An issued credit note cannot be changed.");
319	        }
320	        if (invoice.hasCreditNotesIssued()) {
321	            throw new InvoiceRejectedException("An invoice with an issued credit note cannot be changed.");
322	        }
323	        if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
324	            throw new InvoiceRejectedException(refusal);
325	        }
326	        invoice.reopen();
327	        return true;
328	    }
