330	    /**
331	     * Sends a draft invoice, issuing it today and making it due on the client's terms (or keeping a due
332	     * date set by hand), and records it in the audit; empty if no such invoice. An invoice already
333	     * sent, with no lines, whose discount needs a reason but has none, or whose due date set by hand is
334	     * before today, is refused.
335	     */
336	    @Transactional
337	    public Optional<Invoice> send(Long invoiceId) {
338	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
339	        found.ifPresent(invoice -> {
340	            if (invoice.isVoid()) {
341	                throw new InvoiceRejectedException("A void invoice cannot be sent.");
342	            }
343	            if (!invoice.isDraft()) {
344	                throw new InvoiceRejectedException("This invoice has already been sent.");
345	            }
346	            if (invoice.getLines().isEmpty()) {
347	                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
348	            }
349	            if (invoice.isCreditNote()) {
350	                String refusal = creditNoteRefusal(invoice);
351	                if (refusal != null) {
352	                    throw new InvoiceRejectedException(refusal);
353	                }
354	                issue(invoice);
355	                return;
356	            }
357	            if (invoice.discountLacksReason()) {
358	                throw new InvoiceRejectedException(
359	                        "The discount is more than 20% of the subtotal; give it a reason before sending the invoice.");
360	            }
361	            if (invoice.dueDatePassedBy(today.date())) {
362	                throw new InvoiceRejectedException("The due date (" + invoice.getDueDate()
363	                        + ") is already past; set a later due date before sending the invoice.");
364	            }
365	            markSent(invoice);
366	        });
367	        return found;
368	    }
