370	    /**
371	     * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
372	     * would; drafts with no lines, whose discount needs a reason but has none, or whose due date set by
373	     * hand is already past, stay drafts.
374	     */
375	    @Transactional
376	    public void sendAllDrafts(Long clientId) {
377	        invoices.findByClientIdOrderByIdAsc(clientId).stream()
378	                .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty() && !invoice.discountLacksReason()
379	                        && !invoice.dueDatePassedBy(today.date()))
380	                .forEach(invoice -> {
381	                    if (!invoice.isCreditNote()) {
382	                        markSent(invoice);
383	                    } else if (creditNoteRefusal(invoice) == null) {
384	                        issue(invoice);
385	                    }
386	                });
387	    }
