401	    /**
402	     * Issues the draft credit note today and records it in the audit: its grand total comes off what
403	     * its original still owes, then the retention it holds back; any rest is held on the client's
404	     * account as a credit payment dated today, also recorded in the audit.
405	     */
406	    private void issue(Invoice note) {
407	        BigDecimal rate = taxRate.percent();
408	        Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElseThrow();
409	        // Read again what it has been credited: another credit note may just have been issued against it.
410	        entityManager.refresh(original);
411	        BigDecimal total = note.total(rate);
412	        BigDecimal[] taken = original.creditTaken(total, paid(List.of(original)).get(original.getId()), rate);
413	        note.markIssued(today.date(), rate, taken[0], taken[1]);
414	        invoices.saveAndFlush(note);
415	        audit.record("CREDIT_NOTE_ISSUED id=" + note.getId() + " number=" + note.number() + " invoice="
416	                + note.getCreditOf() + " total=" + total.toPlainString());
417	        BigDecimal rest = total.subtract(taken[0]);
418	        if (rest.signum() > 0) {
419	            recordCreditHeld(payments.saveAndFlush(Payment.fromCreditNote(note, rest)));
420	        }
421	    }
