423	    /**
424	     * Issues the draft today, due on the client's terms, and records it in the audit; then uses the
425	     * client's credit on it (see {@link #applyCredit}).
426	     */
427	    private void markSent(Invoice invoice) {
428	        LocalDate issued = today.date();
429	        invoice.markSent(issued, dueDateFor(invoice.getClientId(), issued));
430	        invoices.saveAndFlush(invoice);
431	        audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + invoice.number()
432	                + " total=" + invoice.total(taxRate.percent()).toPlainString());
433	        applyCredit(invoice);
434	    }
435	
436	    /**
437	     * Uses the client's credit on the invoice just sent, up to what it has due: the oldest payment's
438	     * credit first (lower id first on the same date), each part applied today and recorded in the audit.
439	     */
440	    private void applyCredit(Invoice invoice) {
441	        BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
442	        LocalDate now = today.date();
443	        boolean used = false;
444	        for (Payment payment : payments.findForClient(invoice.getClientId())) {
445	            if (due.signum() <= 0) {
446	                break;
447	            }
448	            BigDecimal credit = payment.credit();
449	            if (credit.signum() <= 0) {
450	                continue;
451	            }
452	            BigDecimal part = credit.min(due);
453	            payment.apply(invoice.getId(), part, now);
454	            payments.saveAndFlush(payment);
455	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
456	                    + part.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
457	            due = due.subtract(part);
458	            used = true;
459	        }
460	        if (used) {
461	            recordWriteOff(invoice);
462	        }
463	    }
