465	    /**
466	     * Records a deposit of the amount on the date from the client: the whole amount is held on the
467	     * client's account as credit, applied to no invoice, and recorded in the audit; empty if no such
468	     * client. The amount has already been checked; a date after today is refused.
469	     */
470	    @Transactional
471	    public Optional<Payment> recordDeposit(Long clientId, BigDecimal amount, LocalDate date) {
472	        if (clients.findById(clientId).isEmpty()) {
473	            return Optional.empty();
474	        }
475	        LocalDate now = today.date();
476	        if (date.isAfter(now)) {
477	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
478	        }
479	        Payment payment = payments.saveAndFlush(Payment.deposit(clientId, amount, date));
480	        audit.record("DEPOSIT_RECORDED id=" + payment.getId() + " client=" + clientId + " amount="
481	                + amount.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
482	        return Optional.of(payment);
483	    }
