485	    /**
486	     * Refunds the amount of the client's unused credit on the date: the oldest payment's credit first
487	     * (lower id first on the same date), then the next, each part recorded in the audit; empty if no
488	     * such client. The amount has already been checked; a date after today or before a payment it
489	     * would come from, or an amount more than the client's credit, is refused.
490	     */
491	    @Transactional
492	    public Optional<Long> refundCredit(Long clientId, BigDecimal amount, LocalDate date) {
493	        if (clients.findById(clientId).isEmpty()) {
494	            return Optional.empty();
495	        }
496	        LocalDate now = today.date();
497	        if (date.isAfter(now)) {
498	            throw new InvoiceRejectedException("The refund date cannot be after today (" + now + ").");
499	        }
500	        List<Payment> from = new ArrayList<>();
501	        List<BigDecimal> parts = new ArrayList<>();
502	        BigDecimal left = amount;
503	        BigDecimal credit = BigDecimal.ZERO;
504	        for (Payment payment : payments.findForClient(clientId)) {
505	            BigDecimal unused = payment.credit();
506	            if (unused.signum() <= 0) {
507	                continue;
508	            }
509	            credit = credit.add(unused);
510	            if (left.signum() <= 0) {
511	                continue;
512	            }
513	            BigDecimal part = unused.min(left);
514	            if (date.isBefore(payment.getDate())) {
515	                throw new InvoiceRejectedException("The refund cannot be dated before the payment of "
516	                        + payment.getDate() + " it would come from.");
517	            }
518	            from.add(payment);
519	            parts.add(part);
520	            left = left.subtract(part);
521	        }
522	        if (left.signum() > 0) {
523	            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of $"
524	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString() + ".");
525	        }
526	        for (int i = 0; i < from.size(); i++) {
527	            Payment payment = from.get(i);
528	            payment.refund(parts.get(i));
529	            payments.saveAndFlush(payment);
530	            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
531	                    + parts.get(i).setScale(2, RoundingMode.UNNECESSARY).toPlainString());
532	        }
533	        return Optional.of(clientId);
534	    }
