536	    /** The unused credit of each client that has any, by client id. */
537	    @Transactional(readOnly = true)
538	    public Map<Long, BigDecimal> credits() {
539	        Map<Long, BigDecimal> credits = new HashMap<>();
540	        for (Payment payment : payments.findNotReversed()) {
541	            BigDecimal credit = payment.credit();
542	            if (credit.signum() > 0) {
543	                credits.merge(payment.getClientId(), credit, BigDecimal::add);
544	            }
545	        }
546	        return credits;
547	    }
