549	    /**
550	     * Voids a sent invoice with no payments, and records it in the audit; empty if no such invoice. A
551	     * draft, an invoice already void, or one with any payment is refused.
552	     */
553	    @Transactional
554	    public Optional<Invoice> voidInvoice(Long invoiceId) {
555	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
556	        found.ifPresent(invoice -> {
557	            if (invoice.isVoid()) {
558	                throw new InvoiceRejectedException("This invoice is already void.");
559	            }
560	            if (invoice.isDraft()) {
561	                throw new InvoiceRejectedException("A draft cannot be voided; only a sent invoice can.");
562	            }
563	            if (invoice.isCreditNote()) {
564	                throw new InvoiceRejectedException("An issued credit note cannot be voided.");
565	            }
566	            if (invoice.hasCreditNotesIssued()) {
567	                throw new InvoiceRejectedException("An invoice with an issued credit note cannot be voided.");
568	            }
569	            if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
570	                throw new InvoiceRejectedException("An invoice with payments cannot be voided.");
571	            }
572	            invoice.markVoid();
573	            invoices.saveAndFlush(invoice);
574	            audit.record("INVOICE_VOIDED id=" + invoice.getId() + " number=" + invoice.number());
575	        });
576	        return found;
577	    }
