585	    /** The date each fully paid invoice was paid (see {@link Invoice#paidOn}); an invoice not fully paid is left out. */
586	    @Transactional(readOnly = true)
587	    public Map<Long, LocalDate> paidOn(List<Invoice> list) {
588	        Map<Long, LocalDate> paidOn = new HashMap<>();
589	        if (list.isEmpty()) {
590	            return paidOn;
591	        }
592	        List<Payment> found = payments.findForInvoices(list.stream().map(Invoice::getId).toList());
593	        BigDecimal rate = taxRate.percent();
594	        for (Invoice i : list) {
