603	    /** What has been paid to each of the invoices; an invoice paid nothing is paid zero. */
604	    @Transactional(readOnly = true)
605	    public Map<Long, BigDecimal> paid(List<Invoice> list) {
606	        Map<Long, BigDecimal> paid = new HashMap<>();
607	        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
608	        if (!list.isEmpty()) {
609	            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
610	                paid.put((Long) row[0], ((BigDecimal) row[1]).setScale(2));
611	            }
612	        }
