616	    /**
617	     * Records a payment of the amount on the date against a sent invoice that still has something
618	     * due, and records it in the audit; empty if no such invoice. The amount has already been
619	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
620	     * invoice already paid, or a date after today
621	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
622	     * already been checked; one that belongs to a different invoice is refused.
623	     */
624	    @Transactional
625	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal amount, LocalDate date, String reference) {
626	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
627	        found.ifPresent(invoice -> {
628	            if (invoice.isDraft()) {
629	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
630	            }
631	            if (invoice.isVoid()) {
632	                throw new InvoiceRejectedException("A void invoice takes no payments.");
633	            }
634	            if (invoice.isCreditNote()) {
635	                throw new InvoiceRejectedException("A credit note takes no payments.");
636	            }
637	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
638	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
639	            if (due.signum() <= 0) {
640	                throw new InvoiceRejectedException("This invoice has already been paid.");
641	            }
642	            BigDecimal applied = amount.min(due);
643	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
644	                throw new InvoiceRejectedException("A part payment must be at least $"
645	                        + invoice.minimumPart(taxRate.percent()).toPlainString()
646	                        + " (10% of the total), unless it settles the invoice.");
647	            }
648	            LocalDate now = today.date();
649	            if (date.isAfter(now)) {
650	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
651	            }
652	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
653	                throw new InvoiceRejectedException(
654	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
655	            }
656	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
657	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
658	                        + " is the reference of a different invoice; this invoice's is "
659	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
660	            }
661	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference));
662	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
663	                    + applied.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
664	            recordWriteOff(invoice);
665	            recordCreditHeld(payment);
666	        });
667	        return found;
668	    }
669	
670	    /**
671	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
672	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
673	     * paying each off in full before the next.
674	     * What it pays beyond everything the client owes is held on the client's account as credit; the
675	     * rest is checked and recorded as a split payment over the invoices it reaches.
676	     * References (empty when none, each already checked) instead limit the payment to the client's
677	     * invoices with those references, applied in the same order; one that is not the reference of any
678	     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
679	     * as credit.
680	     * The payment keeps the reference of the first invoice it reaches.
681	     */
682	    @Transactional
683	    public Payment recordAutoPayment(Long clientId, BigDecimal amount, LocalDate date, List<String> references) {
684	        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
685	        List<Invoice> candidates = ofClient;
686	        if (!references.isEmpty()) {
687	            Set<Long> named = new HashSet<>();
688	            for (String reference : references) {
689	                Invoice invoice = ofClient.stream()
690	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
691	                        .findFirst()
692	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
693	                                + " is not the reference of any of this client's invoices."));
694	                String number = InvoiceNumber.of(invoice.getId());
695	                if (invoice.isDraft()) {
696	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
697	                }
698	                if (invoice.isVoid()) {
699	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
700	                }
701	                if (invoice.isCreditNote()) {
702	                    throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
703	                }
704	                named.add(invoice.getId());
705	            }
706	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
707	        }
708	        List<Invoice> sent = candidates.stream()
709	                .filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote())
710	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
711	                        .thenComparing(Invoice::getId))
712	                .toList();
713	        Map<Long, BigDecimal> paid = paid(sent);
714	        BigDecimal owed = BigDecimal.ZERO;
715	        BigDecimal left = amount;
716	        List<PaymentAllocation> parts = new ArrayList<>();
717	        for (Invoice invoice : sent) {
718	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
719	            if (due.signum() <= 0) {
720	                continue;
721	            }
722	            owed = owed.add(due);
723	            if (left.signum() > 0) {
724	                BigDecimal part = left.min(due);
725	                parts.add(new PaymentAllocation(invoice.getId(), part));
726	                left = left.subtract(part);
727	            }
728	        }
729	        if (owed.signum() <= 0) {
730	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
731	                    : "Those invoices have already been paid.");
732	        }
733	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
734	        return recordSpread(clientId, amount, date, reference, parts, true);
735	    }
