737	    /**
738	     * Records one payment of the amount on the date spread over several of the client's invoices, and
739	     * records each part in the audit. The amounts have already been checked to be more than zero; they
740	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
741	     * and be no more than what it still has due. The date must be no later than today nor before any
742	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
743	     * be the reference of one of the invoices.
744	     */
745	    @Transactional
746	    public Payment recordSplitPayment(Long clientId, BigDecimal amount, LocalDate date, String reference,
747	            List<PaymentAllocation> parts) {
748	        return recordSpread(clientId, amount, date, reference, parts, false);
749	    }
750	
751	    /**
752	     * Records the payment spread over the parts as {@link #recordSplitPayment} does, except that when
753	     * credit may be held the parts may add up to less than the payment: the rest is held on the
754	     * client's account as credit and recorded in the audit.
755	     */
756	    private Payment recordSpread(Long clientId, BigDecimal amount, LocalDate date, String reference,
757	            List<PaymentAllocation> parts, boolean holdCredit) {
758	        if (parts.isEmpty()) {
759	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
760	        }
761	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
762	        if (holdCredit ? sum.compareTo(amount) > 0 : sum.compareTo(amount) != 0) {
763	            throw new InvoiceRejectedException("The amounts for the invoices add up to $"
764	                    + sum.setScale(2).toPlainString() + ", not the $" + amount.setScale(2).toPlainString() + " paid.");
765	        }
766	        LocalDate now = today.date();
767	        if (date.isAfter(now)) {
768	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
769	        }
770	        Set<Long> seen = new HashSet<>();
771	        List<Invoice> spreadOver = new ArrayList<>();
772	        for (PaymentAllocation part : parts) {
773	            if (!seen.add(part.getInvoiceId())) {
774	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
775	            }
776	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
777	                    .filter(i -> i.getClientId().equals(clientId))
778	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
779	            String number = InvoiceNumber.of(invoice.getId());
780	            if (invoice.isDraft()) {
781	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
782	            }
783	            if (invoice.isVoid()) {
784	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
785	            }
786	            if (invoice.isCreditNote()) {
787	                throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
788	            }
789	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
790	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
791	            if (part.getAmount().compareTo(due) > 0) {
792	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
793	                        + number + " is more than the $" + due.toPlainString() + " it has due.");
794	            }
795	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
796	                throw new InvoiceRejectedException("The $" + part.getAmount().setScale(2).toPlainString() + " for "
797	                        + number + " is less than $" + invoice.minimumPart(taxRate.percent()).toPlainString()
798	                        + " (10% of its total), unless it settles the invoice.");
799	            }
800	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
801	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
802	                        + " (" + invoice.getIssueDate() + ").");
803	            }
804	            spreadOver.add(invoice);
805	        }
806	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
807	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
808	                    + " is not the reference of any of the invoices being paid.");
809	        }
810	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts));
811	        for (PaymentAllocation part : parts) {
812	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
813	                    + part.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
814	        }
815	        spreadOver.forEach(this::recordWriteOff);
816	        recordCreditHeld(payment);
817	        return payment;
818	    }
819	
820	    /** Records in the audit what a payment just recorded holds on the client's account as credit, if anything. */
821	    private void recordCreditHeld(Payment payment) {
822	        BigDecimal credit = payment.credit();
823	        if (credit.signum() > 0) {
824	            audit.record("CREDIT_HELD payment=" + payment.getId() + " amount="
825	                    + credit.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
826	        }
827	    }
828	
829	    /** Records in the audit what a payment just recorded left written off on the invoice, if anything. */
830	    private void recordWriteOff(Invoice invoice) {
831	        BigDecimal writtenOff = invoice.writtenOff(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
832	        if (writtenOff.signum() > 0) {
833	            audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + writtenOff.toPlainString());
834	        }
835	    }
836	
837	    /**
838	     * Reverses the payment (a bounced cheque), undoing it on every invoice it was applied to, and
839	     * records it in the audit; empty if no such payment. A payment already reversed, or one that has
840	     * had any of its credit refunded, or credit from a credit note, is refused.
841	     */
842	    @Transactional
843	    public Optional<Payment> reversePayment(Long paymentId) {
844	        Optional<Payment> found = payments.findById(paymentId);
845	        found.ifPresent(payment -> {
846	            if (payment.isReversed()) {
847	                throw new InvoiceRejectedException("This payment has already been reversed.");
848	            }
849	            if (payment.getCreditNote() != null) {
850	                throw new InvoiceRejectedException("This is credit from a credit note, so it cannot be reversed.");
851	            }
852	            if (payment.getRefunded().signum() > 0) {
853	                throw new InvoiceRejectedException("This payment has had credit refunded, so it cannot be reversed.");
854	            }
855	            payment.reverse();
856	            payments.saveAndFlush(payment);
857	            audit.record("PAYMENT_REVERSED id=" + payment.getId() + " amount="
858	                    + payment.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString());
859	        });
860	        return found;
861	    }
862	}
