298	    /**
299	     * The balance of each client that has a sent invoice or credit; a client not listed owes nothing and
300	     * has no credit. Void invoices and credit notes do not count (a credit note comes off its original).
301	     */
302	    @GetMapping("/api/clients/balances")
303	    public List<ClientBalance> balances() {
304	        BigDecimal rate = taxRate.percent();
305	        List<Invoice> sent = invoices.all().stream().filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote()).toList();
306	        Map<Long, BigDecimal> paid = invoices.paid(sent);
307	        LocalDate on = today.date();
308	        Map<Long, BigDecimal[]> owed = new TreeMap<>();
309	        for (Invoice i : sent) {
310	            BigDecimal due = i.amountDue(paid.get(i.getId()), rate);
311	            BigDecimal[] sums = owed.computeIfAbsent(i.getClientId(),
312	                    k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) });
313	            sums[0] = sums[0].add(due).add(i.retentionHeld(rate));
314	            if (i.statusWhenPaid(paid.get(i.getId()), rate, on) == InvoiceStatus.OVERDUE) {
315	                sums[1] = sums[1].add(due);
316	            }
317	        }
318	        Map<Long, BigDecimal> credits = invoices.credits();
319	        credits.keySet().forEach(clientId -> owed.computeIfAbsent(clientId,
320	                k -> new BigDecimal[] { BigDecimal.ZERO.setScale(2), BigDecimal.ZERO.setScale(2) }));
321	        return owed.entrySet().stream().map(e -> {
322	            BigDecimal credit = credits.getOrDefault(e.getKey(), BigDecimal.ZERO).setScale(2);
323	            return new ClientBalance(e.getKey(), e.getValue()[0].subtract(credit).toPlainString(),
324	                    e.getValue()[1].toPlainString(), credit.toPlainString());
325	        }).toList();
326	    }
