64	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
65	    @PostMapping("/reset")
66	    @Transactional
67	    public void reset() {
68	        audit.clear();
69	        jdbc.execute("DELETE FROM app_setting");
70	        jdbc.execute("DELETE FROM payment_allocation");
71	        for (String table : List.of("payment", "invoice_line", "invoice", "client")) {
72	            jdbc.execute("DELETE FROM " + table);
