77	    /**
78	     * Insert the fixture a spec needs; the payload shape evolves with the schema. Store every field
79	     * given, or refuse with HTTP 400 naming it — never ignore one silently (AGENTS.md §4.2).
80	     */
81	    @PostMapping("/seed")
82	    @Transactional
83	    public void seed(@RequestBody Map<String, Object> fixture) {
84	        for (String key : fixture.keySet()) {
85	            if (!FIXTURE_KEYS.contains(key)) {
86	                throw refuse("unsupported fixture key: " + key);
87	            }
88	        }
89	        if (fixture.get("asOf") != null) {
90	            LocalDate asOf = date(fixture.get("asOf"), "asOf");
91	            jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)", Today.AS_OF, asOf.toString());
92	        }
93	        if (fixture.get("settings") != null) {
94	            if (!(fixture.get("settings") instanceof Map<?, ?> settings)) {
95	                throw refuse("settings must be an object");
96	            }
97	            @SuppressWarnings("unchecked")
98	            Map<String, Object> values = (Map<String, Object>) settings;
99	            only(values, SETTINGS_FIELDS, "settings");
100	            if (values.get("taxRate") != null) {
101	                BigDecimal rate = percent(values.get("taxRate"), "settings.taxRate");
102	                jdbc.update("INSERT INTO app_setting (name, setting_value) VALUES (?, ?)", TaxRate.TAX_RATE,
103	                        rate.toPlainString());
104	            }
105	        }
106	        for (Map<String, Object> row : rows(fixture.get("clients"), "clients")) {
107	            only(row, CLIENT_FIELDS, "clients[]");
108	            insert("client", row.get("id"), new String[] {"name", "email", "terms_days", "discount_pct", "tax_exempt"},
109	                    text(row, "name"), text(row, "email"), days(row.get("termsDays"), "clients[].termsDays"),
110	                    percent(row.get("discountPct"), "clients[].discountPct"),
111	                    flag(row.get("taxExempt"), "clients[].taxExempt"));
112	        }
113	        for (Map<String, Object> row : rows(fixture.get("invoices"), "invoices")) {
114	            only(row, INVOICE_FIELDS, "invoices[]");
115	            String status = row.get("status") == null ? "DRAFT" : row.get("status").toString();
116	            if (!STATUSES.contains(status)) {
117	                throw refuse("unsupported value of invoices[].status: " + status);
118	            }
119	            if ("CREDIT_NOTE".equals(status) && row.get("creditOf") == null) {
120	                throw refuse("an invoices[] row with status CREDIT_NOTE needs creditOf");
121	            }
122	            // A credit note that has been sent is an issued credit note.
123	            if ("SENT".equals(status) && row.get("creditOf") != null) {
124	                status = "CREDIT_NOTE";
125	            }
126	            if (row.get("clientId") == null) {
127	                throw refuse("invoices[].clientId is required");
128	            }
129	            Long invoiceId = insert("invoice", row.get("id"),
130	                    new String[] {"client_id", "status", "issue_date", "due_date", "discount_pct", "discount_amount", "discount_cap", "discount_reason", "manual_due_date", "credit_of", "retention_pct", "retention_released_on"},
131	                    id(row.get("clientId")), status,
132	                    row.get("issueDate") == null ? null : date(row.get("issueDate"), "invoices[].issueDate"),
133	                    row.get("dueDate") == null ? null : date(row.get("dueDate"), "invoices[].dueDate"),
134	                    percent(row.get("discountPct"), "invoices[].discountPct"),
135	                    money(row.get("discountAmount"), "invoices[].discountAmount"),
136	                    row.get("discountCap") == null ? null : money(row.get("discountCap"), "invoices[].discountCap"),
137	                    row.get("discountReason") == null ? null : row.get("discountReason").toString(),
138	                    flag(row.get("manualDueDate"), "invoices[].manualDueDate"),
139	                    row.get("creditOf") == null ? null : id(row.get("creditOf")),
140	                    percent(row.get("retentionPct"), "invoices[].retentionPct"),
141	                    row.get("retentionReleasedOn") == null ? null
142	                            : date(row.get("retentionReleasedOn"), "invoices[].retentionReleasedOn"));
143	            for (Map<String, Object> line : rows(row.get("lineItems"), "invoices[].lineItems")) {
144	                only(line, LINE_FIELDS, "invoices[].lineItems[]");
145	                insert("invoice_line", line.get("id"),
146	                        new String[] {"invoice_id", "description", "qty", "unit_price", "tax_exempt", "discount_pct", "tax_rate"},
147	                        invoiceId, text(line, "description"),
148	                        cents(line.get("qty"), "invoices[].lineItems[].qty"),
149	                        cents(line.get("unitPrice"), "invoices[].lineItems[].unitPrice"),
150	                        flag(line.get("taxExempt"), "invoices[].lineItems[].taxExempt"),
151	                        percent(line.get("discountPct"), "invoices[].lineItems[].discountPct"),
152	                        line.get("taxRate") == null ? null : percent(line.get("taxRate"), "invoices[].lineItems[].taxRate"));
153	            }
154	        }
155	        for (Map<String, Object> row : rows(fixture.get("payments"), "payments")) {
156	            only(row, PAYMENT_FIELDS, "payments[]");
157	            if (row.get("clientId") == null) {
158	                throw refuse("payments[].clientId is required");
159	            }
160	            if (row.get("date") == null) {
161	                throw refuse("payments[].date is required");
162	            }
163	            Long paymentId = insert("payment", row.get("id"), new String[] {"client_id", "amount", "payment_date", "reference", "reversed", "refunded", "credit_note"},
164	                    id(row.get("clientId")), cents(row.get("amount"), "payments[].amount"),
165	                    date(row.get("date"), "payments[].date"),
166	                    row.get("reference") == null ? null : row.get("reference").toString(),
167	                    flag(row.get("reversed"), "payments[].reversed"),
168	                    money(row.get("refunded"), "payments[].refunded"),
169	                    row.get("creditNote") == null ? null : id(row.get("creditNote")));
170	            for (Map<String, Object> allocation : rows(row.get("allocations"), "payments[].allocations")) {
171	                only(allocation, ALLOCATION_FIELDS, "payments[].allocations[]");
172	                if (allocation.get("invoiceId") == null) {
173	                    throw refuse("payments[].allocations[].invoiceId is required");
174	                }
175	                jdbc.update("INSERT INTO payment_allocation (payment_id, invoice_id, amount, applied_date) VALUES (?, ?, ?, ?)",
176	                        paymentId, id(allocation.get("invoiceId")),
177	                        cents(allocation.get("amount"), "payments[].allocations[].amount"),
178	                        allocation.get("date") == null ? null : date(allocation.get("date"), "payments[].allocations[].date"));
179	            }
180	        }
181	        // An issued credit note keeps its grand total, which comes off what its original owes, then the
182	        // retention it holds back, in the order they were issued; any rest is the client's credit.
183	        BigDecimal rate = taxRate.percent();
184	        for (Long noteId : jdbc.queryForList("SELECT id FROM invoice WHERE status = 'CREDIT_NOTE' ORDER BY id", Long.class)) {
185	            Invoice note = invoices.findWithLinesById(noteId).orElseThrow();
186	            BigDecimal total = note.total(rate);
187	            BigDecimal applied = BigDecimal.ZERO;
188	            BigDecimal toRetention = BigDecimal.ZERO;
189	            Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElse(null);
190	            if (original != null) {
191	                entityManager.refresh(original);
192	                BigDecimal paid = payments.paidTo(List.of(original.getId())).stream()
193	                        .map(r -> (BigDecimal) r[1]).findFirst().orElse(BigDecimal.ZERO);
194	                BigDecimal[] taken = original.creditTaken(total, paid, rate);
195	                applied = taken[0];
196	                toRetention = taken[1];
197	            }
198	            jdbc.update("UPDATE invoice SET credit_total = ?, credit_applied = ?, credit_retention = ? WHERE id = ?",
199	                    total, applied, toRetention, noteId);
200	        }
201	        // Keep generated ids clear of the seeded ones.
202	        for (String table : List.of("client", "invoice", "invoice_line", "payment")) {
203	            Long next = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) + 1 FROM " + table, Long.class);
204	            jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + next);
205	        }
206	    }
