310	    /** Insert a row with the given id, or a generated one when none is given; returns the id. */
311	    private Long insert(String table, Object id, String[] columns, Object... values) {
312	        String cols = String.join(", ", columns);
313	        String marks = String.join(", ", Collections.nCopies(columns.length, "?"));
314	        if (id != null) {
315	            Object[] args = new Object[values.length + 1];
316	            args[0] = id(id);
317	            System.arraycopy(values, 0, args, 1, values.length);
318	            jdbc.update("INSERT INTO " + table + " (id, " + cols + ") VALUES (?, " + marks + ")", args);
319	            return id(id);
320	        }
321	        jdbc.update("INSERT INTO " + table + " (" + cols + ") VALUES (" + marks + ")", values);
322	        return jdbc.queryForObject("SELECT MAX(id) FROM " + table, Long.class);
323	    }
324	
325	    /** A whole number of days, not negative; null when left out. */
326	    private static Integer days(Object value, String field) {
327	        if (value == null) {
328	            return null;
329	        }
330	        try {
331	            int days = new BigDecimal(value.toString()).intValueExact();
332	            if (days < 0) {
333	                throw refuse(field + " cannot be negative, not " + value);
334	            }
335	            return days;
336	        } catch (NumberFormatException | ArithmeticException e) {
337	            throw refuse(field + " must be a whole number of days, not " + value);
338	        }
339	    }
340	
341	    /** A true/false flag; false when left out. */
342	    private static boolean flag(Object value, String where) {
343	        if (value == null) {
344	            return false;
345	        }
346	        if (!(value instanceof Boolean b)) {
347	            throw refuse(where + " must be true or false");
348	        }
349	        return b;
350	    }
351	
352	    private static void only(Map<String, Object> row, Set<String> fields, String where) {
353	        for (String field : row.keySet()) {
354	            if (!fields.contains(field)) {
355	                throw refuse("unsupported field: " + where + "." + field);
356	            }
357	        }
358	    }
359	
360	    private static Long id(Object value) {
361	        if (value instanceof Number n) {
362	            return n.longValue();
363	        }
364	        try {
365	            return Long.valueOf(value.toString());
366	        } catch (NumberFormatException e) {
367	            throw refuse("not an id: " + value);
368	        }
369	    }
370	
371	    private static LocalDate date(Object value, String field) {
372	        try {
373	            return LocalDate.parse(value.toString());
374	        } catch (DateTimeParseException e) {
375	            throw refuse(field + " must be a yyyy-mm-dd date, not " + value);
376	        }
377	    }
378	
379	    /** A number stored to the cent; refuses a value it could only store by rounding. */
380	    private static BigDecimal cents(Object value, String field) {
381	        if (value == null) {
382	            throw refuse(field + " is required");
383	        }
384	        BigDecimal number;
385	        try {
386	            number = new BigDecimal(value.toString());
387	        } catch (NumberFormatException e) {
388	            throw refuse(field + " must be a number, not " + value);
389	        }
390	        if (number.stripTrailingZeros().scale() > 2) {
391	            throw refuse(field + " can have at most two decimals, not " + value);
392	        }
393	        return number;
394	    }
395	
396	    /** A percentage from 0 to 100 with at most two decimals; none given is zero. */
397	    private static BigDecimal percent(Object value, String field) {
398	        if (value == null) {
399	            return BigDecimal.ZERO;
400	        }
401	        BigDecimal number = cents(value, field);
402	        if (number.signum() < 0 || number.compareTo(BigDecimal.valueOf(100)) > 0) {
403	            throw refuse(field + " must be from 0 to 100, not " + value);
404	        }
405	        return number;
406	    }
407	
408	    /** An optional amount of money, not negative and to the cent; 0 when left out. */
409	    private static BigDecimal money(Object value, String field) {
410	        if (value == null) {
411	            return BigDecimal.ZERO;
412	        }
413	        BigDecimal number = cents(value, field);
414	        if (number.signum() < 0) {
415	            throw refuse(field + " cannot be negative, not " + value);
416	        }
417	        return number;
418	    }
419	
420	    @SuppressWarnings("unchecked")
421	    private static List<Map<String, Object>> rows(Object value, String key) {
422	        if (value == null) {
423	            return List.of();
424	        }
425	        if (!(value instanceof List<?> list)) {
426	            throw refuse(key + " must be a list of rows");
427	        }
428	        List<Map<String, Object>> out = new ArrayList<>();
429	        for (Object o : list) {
430	            if (!(o instanceof Map<?, ?> m)) {
431	                throw refuse(key + " must be a list of rows");
432	            }
433	            out.add((Map<String, Object>) m);
434	        }
435	        return out;
436	    }
437	
438	    private static String text(Map<String, Object> row, String field) {
439	        Object v = row.get(field);
440	        return v == null ? "" : v.toString();
441	    }
442	
443	    private static ResponseStatusException refuse(String message) {
444	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, message);
445	    }
446	}
