726	        this.discountForm.reset();
727	        this.savingDiscount.set(false);
728	      },
729	      error: (e: HttpErrorResponse) => {
730	        const detail: unknown = e.error?.detail;
731	        this.discountError.set(
732	          typeof detail === 'string' && detail ? detail : 'The discount could not be applied.',
733	        );
734	        this.savingDiscount.set(false);
735	      },
736	    });
737	  }
738	
739	  protected paymentRecorded(detail: InvoiceDetail): void {
740	    this.invoice.set(detail);
741	    this.changed.emit(detail);
742	  }
743	
744	  // A payment was spread over several invoices: show this one again with its share.
745	  protected splitRecorded(invoiceId: number, list: InvoiceSummary[]): void {
746	    this.split.emit(list);
747	    this.service.open(invoiceId).subscribe((detail) => this.invoice.set(detail));
748	  }
749	
750	  protected setDueDate(invoiceId: number): void {
751	    const dueDate = this.dueForm.getRawValue().dueDate.trim();
752	    if (!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)) {
753	      this.dueForm.markAllAsTouched();
754	      this.dueError.set('Enter the due date as a date, like 2026-04-30.');
755	      return;
756	    }
757	    this.savingDue.set(true);
758	    this.dueError.set('');
759	    this.service.setDueDate(invoiceId, dueDate).subscribe({
760	      next: (detail) => {
761	        this.invoice.set(detail);
762	        this.changed.emit(detail);
763	        this.dueForm.reset();
764	        this.savingDue.set(false);
765	      },
766	      error: (e: HttpErrorResponse) => {
767	        const detail: unknown = e.error?.detail;
768	        this.dueError.set(
769	          typeof detail === 'string' && detail ? detail : 'The due date could not be set.',
770	        );
771	        this.savingDue.set(false);
772	      },
773	    });
774	  }
775	
776	  protected setRetention(invoiceId: number): void {
777	    const pct = this.retentionForm.getRawValue().pct.trim().replace(/%$/, '').trim();
778	    const problem = problemWithRetention(pct);
779	    if (problem) {
780	      this.retentionForm.markAllAsTouched();
781	      this.retentionError.set(problem);
782	      return;
783	    }
784	    this.savingRetention.set(true);
785	    this.retentionError.set('');
786	    this.service.setRetention(invoiceId, pct).subscribe({
787	      next: (detail) => {
788	        this.invoice.set(detail);
789	        this.changed.emit(detail);
790	        this.retentionForm.reset();
791	        this.savingRetention.set(false);
792	      },
793	      error: (e: HttpErrorResponse) => {
794	        const detail: unknown = e.error?.detail;
795	        this.retentionError.set(
796	          typeof detail === 'string' && detail ? detail : 'The retention could not be set.',
797	        );
798	        this.savingRetention.set(false);
799	      },
800	    });
801	  }
802	
803	  protected releaseRetention(invoiceId: number): void {
804	    this.releasing.set(true);
805	    this.releaseError.set('');
806	    this.service.releaseRetention(invoiceId).subscribe({
807	      next: (detail) => {
808	        this.invoice.set(detail);
809	        this.changed.emit(detail);
810	        this.releasing.set(false);
811	      },
812	      error: (e: HttpErrorResponse) => {
813	        const detail: unknown = e.error?.detail;
814	        this.releaseError.set(
815	          typeof detail === 'string' && detail ? detail : 'The retention could not be released.',
816	        );
817	        this.releasing.set(false);
818	      },
819	    });
820	  }
821	
822	  // Sends a draft; an issued credit note also changes what its original owes, so the client's
823	  // invoices are shown again.
824	  protected send(inv: InvoiceDetail): void {
825	    this.sending.set(true);
826	    this.sendError.set('');
827	    this.service.send(inv.id).subscribe({
828	      next: (detail) => {
829	        this.invoice.set(detail);
830	        this.changed.emit(detail);
831	        if (detail.creditOf !== null) {
832	          this.service.forClient(detail.clientId).subscribe((list) => this.split.emit(list));
833	        }
834	        this.sending.set(false);
835	      },
836	      error: (e: HttpErrorResponse) => {
837	        const detail: unknown = e.error?.detail;
838	        this.sendError.set(
839	          typeof detail === 'string' && detail ? detail : 'The invoice could not be sent.',
840	        );
841	        this.sending.set(false);
842	      },
843	    });
844	  }
845	
846	  protected duplicate(invoiceId: number): void {
847	    this.duplicating.set(true);
848	    this.duplicateError.set('');
849	    this.service.duplicate(invoiceId).subscribe({
850	      next: (detail) => {
851	        this.duplicating.set(false);
852	        this.duplicated.emit(detail);
853	      },
854	      error: (e: HttpErrorResponse) => {
855	        const detail: unknown = e.error?.detail;
856	        this.duplicateError.set(
857	          typeof detail === 'string' && detail ? detail : 'The invoice could not be duplicated.',
858	        );
859	        this.duplicating.set(false);
860	      },
861	    });
862	  }
863	
864	  protected creditNote(invoiceId: number): void {
865	    this.crediting.set(true);
866	    this.creditError.set('');
867	    this.service.creditNote(invoiceId).subscribe({
868	      next: (detail) => {
869	        this.crediting.set(false);
870	        this.credited.emit(detail);
871	      },
872	      error: (e: HttpErrorResponse) => {
873	        const detail: unknown = e.error?.detail;
874	        this.creditError.set(
875	          typeof detail === 'string' && detail ? detail : 'The credit note could not be started.',
876	        );
877	        this.crediting.set(false);
878	      },
879	    });
880	  }
881	
882	  protected voidInvoice(invoiceId: number): void {
883	    this.voiding.set(true);
884	    this.voidError.set('');
885	    this.service.void(invoiceId).subscribe({
886	      next: (detail) => {
887	        this.invoice.set(detail);
888	        this.changed.emit(detail);
889	        this.voiding.set(false);
890	      },
891	      error: (e: HttpErrorResponse) => {
892	        const detail: unknown = e.error?.detail;
893	        this.voidError.set(
894	          typeof detail === 'string' && detail ? detail : 'The invoice could not be voided.',
895	        );
896	        this.voiding.set(false);
897	      },
898	    });
899	  }
900	
901	  // A payment was reversed: show this invoice again, and the client's other invoices it was applied to.
902	  protected reversePayment(invoiceId: number, clientId: number, paymentId: number): void {
903	    this.reversing.set(true);
904	    this.reverseError.set('');
905	    this.service.reversePayment(invoiceId, paymentId).subscribe({
906	      next: (detail) => {
907	        this.invoice.set(detail);
908	        this.changed.emit(detail);
909	        this.service.forClient(clientId).subscribe((list) => this.split.emit(list));
910	        this.reversing.set(false);
911	      },
912	      error: (e: HttpErrorResponse) => {
913	        const detail: unknown = e.error?.detail;
914	        this.reverseError.set(
915	          typeof detail === 'string' && detail ? detail : 'The payment could not be reversed.',
916	        );
917	        this.reversing.set(false);
918	      },
919	    });
920	  }
921	}
